from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
needle = '</div><div className={`contact-guard ${contactUnlocked ? "unlocked" : ""}`}>'
card = """</div><div className={`wallet-escrow-card wallet-${paymentStatus}`}><div className="wallet-card-head"><div><span className="mini-label">محفظة نجدة · دفع محمي</span><strong>{paymentStatus === "pending" ? "احجز المبلغ قبل بدء الخدمة" : paymentStatus === "held" ? "المبلغ محجوز بأمان" : "تم تحرير المستحقات"}</strong></div><Banknote size={19} /></div><div className="wallet-breakdown"><span><small>قيمة الخدمة</small><strong>{activeServicePrice} ر.س</strong></span><span><small>نسبة نجدة (١٠٪)</small><strong>{activePlatformFee} ر.س</strong></span><span><small>صافي مقدم الخدمة</small><strong>{activeProviderNet} ر.س</strong></span></div>{paymentStatus === "pending" && <><p>يدفع العميل مسبقًا إلى محفظة الموقع، ويبقى المبلغ محجوزًا حتى تأكيد الإتمام.</p><button onClick={holdPayment} disabled={holdWalletFunds.isPending}>{holdWalletFunds.isPending ? "جارٍ الحجز..." : "حجز المبلغ من المحفظة"}</button></>}{paymentStatus === "held" && <><p>المبلغ محفوظ داخل نجدة. بعد انتهاء العمل، اضغط تأكيد الإتمام لتحويل الصافي لمقدم الخدمة.</p><button onClick={confirmCompletion} disabled={releaseWalletFunds.isPending || trackingProgress < 100}>{releaseWalletFunds.isPending ? "جارٍ التحرير..." : trackingProgress < 100 ? "بانتظار وصول مقدم الخدمة" : "تأكيد إتمام الخدمة وتحرير المبلغ"}</button></>}{paymentStatus === "released" && <p className="wallet-success-note"><Check size={14} /> تم خصم نسبة المنصة وتحويل صافي المبلغ لمقدم الخدمة.</p>}</div><div className={`contact-guard ${contactUnlocked ? "unlocked" : ""}`}>"""
if needle not in s:
    raise SystemExit('wallet insertion point not found')
p.write_text(s.replace(needle, card, 1))
